#include <libstud/regex.hxx>

#include <array>
#include <string>
#include <cstddef> // size_t

#ifdef __cpp_lib_three_way_comparison
#  include <compare>
#endif

#include "constexpr_char_traits.hxx"
#include "make_string.hxx"
#include "test_comparisons.hxx"
#include "test_macros.hxx"

#undef NDEBUG
#include <cassert>

using namespace stud::regex;

using std::string;
using std::wstring;
using std::basic_string;
using std::array;
using std::size_t;

#ifdef __cpp_lib_three_way_comparison
using std::strong_ordering;
using std::weak_ordering;
using std::partial_ordering;
#endif

#define SV(S) MAKE_STRING_VIEW(CharT, S)

template <class CharT>
void
test(const basic_string<CharT>& x, const basic_string<CharT>& y, bool doCStrTests = true)
{
    typedef basic_string<CharT> string;
    typedef sub_match<typename string::const_iterator> sub_match;
#ifdef __cpp_lib_three_way_comparison
    AssertOrderReturn<strong_ordering, sub_match>();
    AssertOrderReturn<strong_ordering, sub_match, string>();
#else
    AssertComparisonsReturnBool<sub_match>();
    AssertComparisonsReturnBool<sub_match, string>();
#endif
    sub_match sm1;
    sm1.first = x.begin();
    sm1.second = x.end();
    sm1.matched = true;
    sub_match sm2;
    sm2.first = y.begin();
    sm2.second = y.end();
    sm2.matched = true;

    assert(testComparisons(sm1, sm2, x == y, x < y));
    assert(testComparisons(x, sm2, x == y, x < y));
    assert(testComparisons(sm1, y, x == y, x < y));
#ifdef __cpp_lib_three_way_comparison
    assert(testOrder(sm1, sm2, x <=> y));
    assert(testOrder(x, sm2, x <=> y));
    assert(testOrder(sm1, y, x <=> y));
#endif

    if (doCStrTests) {
        assert(testComparisons(x.c_str(), sm2, x == y, x < y));
        assert(testComparisons(sm1, y.c_str(), x == y, x < y));
#ifdef __cpp_lib_three_way_comparison
        assert(testOrder(x.c_str(), sm2, x <=> y));
        assert(testOrder(sm1, y.c_str(), x <=> y));
#endif
    }

    assert(testComparisons(x[0], sm2, string(1, x[0]) == y, string(1, x[0]) < y));
    assert(testComparisons(sm1, y[0], x == string(1, y[0]), x < string(1, y[0])));
#ifdef __cpp_lib_three_way_comparison
    assert(testOrder(x[0], sm2, (string(1, x[0]) <=> y)));
    assert(testOrder(sm1, y[0], x <=> (string(1, y[0]))));
#endif
}

#ifdef __cpp_lib_three_way_comparison
template <class CharT, class Ordering>
struct char_traits : public constexpr_char_traits<CharT> {
    using comparison_category = Ordering;
};

template <class T, class Ordering = strong_ordering>
constexpr void test() {
  AssertOrderAreNoexcept<T>();
  AssertOrderReturn<Ordering, T>();

  using CharT = typename T::value_type;

  // sorted values
  array s = [] {
    array input{SV(""), SV("abc"), SV("abcdef")};
    return array{
        T{input[0].begin(), input[0].end()}, T{input[1].begin(), input[1].end()}, T{input[2].begin(), input[2].end()}};
  }();
  auto ctor = [](const T& string) {
    sub_match<typename T::const_iterator> sm;
    sm.first   = string.begin();
    sm.second  = string.end();
    sm.matched = true;
    return sm;
  };
  array sm{ctor(s[0]), ctor(s[1]), ctor(s[2])};

  for (size_t i = 0; i < s.size(); ++i) {
    for (size_t j = 0; j < s.size(); ++j) {
      assert(testOrder(s[i], sm[j], i == j ? Ordering::equivalent : i < j ? Ordering::less : Ordering::greater));
    }
  }
}

template <class CharT>
constexpr void test_all_orderings() {
  test<basic_string<CharT>>(); // Strong ordering in its char_traits
  test<basic_string<CharT, constexpr_char_traits<CharT>>,
       weak_ordering>(); // No ordering in its char_traits
  test<basic_string<CharT, char_traits<CharT, weak_ordering>>, weak_ordering>();
  test<basic_string<CharT, char_traits<CharT, partial_ordering>>, partial_ordering>();
}
#endif //  TEST_STD_VER > 17

int main(int, char**)
{
    test(string("123"), string("123"));
    test(string("1234"), string("123"));
    test(string("123\000" "56", 6), string("123\000" "56", 6), false);
#ifdef __cpp_lib_three_way_comparison
    test_all_orderings<char>();
#endif

#ifndef TEST_HAS_NO_WIDE_CHARACTERS
    test(wstring(L"123"), wstring(L"123"));
    test(wstring(L"1234"), wstring(L"123"));
    test(wstring(L"123\000" L"56", 6), wstring(L"123\000" L"56", 6), false);
#ifdef __cpp_lib_three_way_comparison
    test_all_orderings<wchar_t>();
#endif
#endif // TEST_HAS_NO_WIDE_CHARACTERS

  return 0;
}
